import{describe,it,expect,beforeEach}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function setupThemeDOM(){document.body.innerHTML='\n    <button id="theme-toggle" title="Toggle Light Mode" aria-label="Toggle Light Mode">\n      <svg class="theme-toggle-icon" viewBox="0 0 24 24">\n        <path d="M21 12.8A8.8 8.8 0 0 1 11.2 3 8.8 8.8 0 1 0 21 12.8Z" />\n      </svg>\n    </button>\n  ',localStorage.removeItem("theme"),document.body.classList.remove("light-theme")}function initThemeToggle(){const e=document.getElementById("theme-toggle");if(!e)return;if(e.dataset.listenerBound)return;e.dataset.listenerBound="true";const t=t=>{t?(e.innerHTML='\n        <svg class="theme-toggle-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">\n          <path d="M12 3v2M12 19v2M5 5l1.5 1.5M17.5 17.5L19 19M3 12h2M19 12h2M5 19l1.5-1.5M17.5 6.5L19 5" />\n          <circle cx="12" cy="12" r="4.5" />\n        </svg>\n      ',e.setAttribute("title","Toggle Dark Mode"),e.setAttribute("aria-label","Toggle Dark Mode")):(e.innerHTML='\n        <svg class="theme-toggle-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">\n          <path d="M21 12.8A8.8 8.8 0 0 1 11.2 3 8.8 8.8 0 1 0 21 12.8Z" fill="currentColor" />\n        </svg>\n      ',e.setAttribute("title","Toggle Light Mode"),e.setAttribute("aria-label","Toggle Light Mode"))};"light"===localStorage.getItem("theme")?(document.body.classList.add("light-theme"),t(!0)):t(!1),e.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");t(e);const o=e?"light":"dark";localStorage.setItem("theme",o)})}describe("Theme toggle — default state (dark mode)",()=>{beforeEach(()=>{setupThemeDOM()}),it("default theme (no localStorage) shows dark mode icon",()=>{initThemeToggle();const e=document.getElementById("theme-toggle");expect(document.body.classList.contains("light-theme")).toBe(!1),expect(e.innerHTML).toContain("12.8A8.8 8.8"),expect(e.getAttribute("title")).toBe("Toggle Light Mode")}),it("click toggles to light theme",()=>{initThemeToggle();const e=document.getElementById("theme-toggle");e.click(),expect(document.body.classList.contains("light-theme")).toBe(!0),expect(localStorage.getItem("theme")).toBe("light"),expect(e.innerHTML).toContain("circle"),expect(e.getAttribute("title")).toBe("Toggle Dark Mode")}),it("click twice toggles back to dark theme",()=>{initThemeToggle();const e=document.getElementById("theme-toggle");e.click(),e.click(),expect(document.body.classList.contains("light-theme")).toBe(!1),expect(localStorage.getItem("theme")).toBe("dark"),expect(e.getAttribute("title")).toBe("Toggle Light Mode")})}),describe("Theme toggle — persisted light mode",()=>{beforeEach(()=>{setupThemeDOM(),localStorage.setItem("theme","light")}),it("reads light theme from localStorage on init",()=>{initThemeToggle();const e=document.getElementById("theme-toggle");expect(document.body.classList.contains("light-theme")).toBe(!0),expect(e.getAttribute("title")).toBe("Toggle Dark Mode")}),it("click toggles from light back to dark",()=>{initThemeToggle();const e=document.getElementById("theme-toggle");e.click(),expect(document.body.classList.contains("light-theme")).toBe(!1),expect(localStorage.getItem("theme")).toBe("dark"),expect(e.getAttribute("title")).toBe("Toggle Light Mode")})}),describe("Theme toggle — localStorage persistence",()=>{function e(){document.body.innerHTML='\n      <button id="theme-toggle" title="Toggle Light Mode" aria-label="Toggle Light Mode">\n        <svg class="theme-toggle-icon" viewBox="0 0 24 24">\n          <path d="M21 12.8A8.8 8.8 0 0 1 11.2 3 8.8 8.8 0 1 0 21 12.8Z" />\n        </svg>\n      </button>\n    ',document.body.classList.remove("light-theme")}beforeEach(()=>{setupThemeDOM()}),it("persists theme across simulated page reloads",()=>{initThemeToggle();document.getElementById("theme-toggle").click(),expect(localStorage.getItem("theme")).toBe("light"),e(),initThemeToggle(),expect(document.body.classList.contains("light-theme")).toBe(!0),expect(document.getElementById("theme-toggle").getAttribute("title")).toBe("Toggle Dark Mode")}),it("dark theme also persists to localStorage",()=>{initThemeToggle();const t=document.getElementById("theme-toggle");t.click(),t.click(),expect(localStorage.getItem("theme")).toBe("dark"),e(),initThemeToggle(),expect(document.body.classList.contains("light-theme")).toBe(!1)})}),describe("Theme toggle — edge cases",()=>{beforeEach(()=>{setupThemeDOM()}),it("is idempotent (safe to call multiple times)",()=>{initThemeToggle(),initThemeToggle();const e=document.getElementById("theme-toggle");e.click(),expect(localStorage.getItem("theme")).toBe("light"),e.click(),expect(localStorage.getItem("theme")).toBe("dark")}),it("handles missing theme button gracefully",()=>{document.body.innerHTML="",expect(()=>initThemeToggle()).not.toThrow()})});